#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
bool is_valid(const char*s){int n=0,sum=0;for(;*s;s++){if(*s=='-')continue;int d;if(isdigit((unsigned char)*s))d=*s-'0';else if(*s=='X'&&n==9)d=10;else return false;if(n>=10)return false;sum+=d*(10-n++);}return n==10&&sum%11==0;}

